/*
 * Icon's built-in functions and keywords, and the preprocessor's
 * predefined symbols (the Go reference's internal/builtin): the
 * catalogue is builtin.inc, generated by tests/genbuiltin.sh.
 */
#ifndef GCON_BUILTIN_H
#define GCON_BUILTIN_H

#include <stdbool.h>
#include <stddef.h>

typedef struct BuiltinFunc {
	const char *name;
	int arity;             /* number of parameters, or -1 if variadic */
	const char *signature; /* e.g. "left(s1,i,s2)" */
	const char *summary;   /* one line, from the Icon runtime sources */
	bool graphics;         /* part of the graphics facilities */
	bool gcon;             /* a gcon extension, not in Icon 9.5 */
} BuiltinFunc;

typedef struct Keyword { /* without its "&" */
	const char *name, *summary;
	bool gcon;
} Keyword;

/* A symbol the preprocessor defines (as 1) on systems with the
 * corresponding feature, e.g. _UNIX or _GRAPHICS. */
typedef struct Predefined {
	const char *name;
	const char *feature; /* the &features entry, or "" if unconditional */
} Predefined;

/* Lookups by name (n bytes); NULL if there is none. */
const BuiltinFunc *builtin_function(const char *name, size_t n);
const Keyword *builtin_keyword(const char *name, size_t n);
const Predefined *builtin_predefined(const char *name, size_t n);

/* The whole catalogue, functions and keywords sorted by name. */
const BuiltinFunc *builtin_functions(size_t *n);
const Keyword *builtin_keywords(size_t *n);

#endif
